#!/bin/bash
#
# This Linux script "uploads" selected files of the Lisa OS source tree onto the
# ProFile disk image file LOS_Compilation_Base_original.image (present in this folder).
# The folder with the Lisa OS source files is given as the first command-line
# argument.
# 
# See the adjacent README.MD file for detailed usage instructions.
#
# Brief usage instructions (a modified version of the instructions at https://github.com/alexthecat123/LisaSourceCompilation by Alexander McLeod):
# 1. Download the file lisa-source.zip from https://info.computerhistory.org/apple-lisa-code and unzip it.
# 3. cd ... folder-with-unzipped-files.... There should be one sub-folder, named Lisa_Source.
# 4. Download Alexander McLeod's https://github.com/alexthecat123/LisaSourceCompilation/blob/main/scripts/patch_files.py utility and run it: 
#    python3 patch_files.py Lisa_Source . It should print "Successfully applied 248/248 patches".
# 5. cd ... the folder where this shell script is.
# 6. run this script: ./upload_files.sh <folder-with-Lisa_Source-files>
#    It will "upload" 862 files onto the disk image. Observe the final message, it should print 
#    "Done: 862 file(s) added, 0 already present, 0 failure(s)" the first time you run it.
# 7. There you have it. Mount the LOS_Compilation_Base_original.image disk image in the LisaEm emulator
#    or on a real Lisa using an ESProfile hardware emulator,
#    boot into Workshop and run "<ALEX/MAKE/ALL_NODISKS2" to build everything except Lisa Guide.
#
# The possible exit codes of each individual file upload are: 0 = success, added; 3 = a file with
# the same name is already on the volume (counted as "already present", not
# a failure, so the script can safely be re-run); anything else = failure.
# The host files are unix-converted Lisa text files named "<name>.unix.txt";
# on the disk image each one is stored under the Lisa file name "<name>.TEXT".
#
# The disk image file LOS_Compilation_Base_original.image present in this folder is a copy of 
# https://github.com/alexthecat123/LisaSourceCompilation/blob/main/LOS%20Compilation%20Base.image.zip .
# It was created by Alexander McLeod, the owner of that repository.
# The file contains a fresh installation of LOS 3.0 and Workshop 3.0, plus his build scripts.
# Credits go to him for preparing it and for figuring out how to compile the LOS sources.


set -u

if [ $# -lt 1 ] || [ -z "${1:-}" ]; then
    echo "Usage: $0 <folder-containing-all-Lisa-OS-Source-files>" >&2
    exit 2
fi
SOURCE_ROOT="$1"
# Make it an absolute path before cd-ing into this script's own folder
# (the disk image lives there and the tool is one folder up).
case "$SOURCE_ROOT" in
    /*) ;;
    *) SOURCE_ROOT="$(pwd)/$SOURCE_ROOT" ;;
esac
SOURCE_ROOT="${SOURCE_ROOT%/}"
cd "$(dirname "$0")"

IMAGE="LOS_Compilation_Base.image"
APPS="$SOURCE_ROOT/APPS"
LISA_OS="$SOURCE_ROOT/LISA_OS"

if [ ! -d "$SOURCE_ROOT" ]; then
    echo "ERROR: folder '$SOURCE_ROOT' does not exist." >&2
    exit 1
fi
if [ ! -d "$APPS" ]; then
    echo "ERROR: no APPS subfolder found in '$SOURCE_ROOT'." >&2
    exit 1
fi
if [ ! -d "$LISA_OS" ]; then
    echo "ERROR: no LISA_OS subfolder found in '$SOURCE_ROOT'." >&2
    exit 1
fi
if [ ! -f "$IMAGE" ]; then
    echo "ERROR: disk image '$IMAGE' not found in '$(pwd)'." >&2
    exit 1
fi

ok=0
skip=0
fail=0

# LOS has a bug (in the source pascal file source-fsprim.text.unix.txt) where overwriting a file with a larger file corrupts the file (if certain conditions are met). 
# The bug is present in file system.os.
# And the LOS build script does exactly that: it builds a new system.os file that is slightly larger than the current one, and then overwrite the current one,
# which corrupts the file system, and at the next boot we get an 10730 boot error (system.os is corrupted).
# So, ironically, the bug in system.os causes corruption of file system.os.
# Our workaround is to pad the original system.os file (of size 185344 bytes) to a new size of 194,000 bytes before running the compilations,
# so that the generated system.os file (of size 193,024 bytes) will be smaller than the current file (of size 194,000), so overwriting it would work just fine.
# The "replace" command does not have such bug, and is able to successfully replace the file.
python3 ../LisaFileSystemToolPerFile.py replace "$IMAGE" system.os system.os ; case $? in 0) ok=$((ok+1));; 3) skip=$((skip+1));; *) fail=$((fail+1));; esac

# Some build macros:
python3 ../LisaFileSystemToolPerFile.py add "$IMAGE" MAKE-ALL_NODISKS2.TEXT ALEX/MAKE/ALL_NODISKS2.TEXT ; case $? in 0) ok=$((ok+1));; 3) skip=$((skip+1));; *) fail=$((fail+1));; esac
python3 ../LisaFileSystemToolPerFile.py add "$IMAGE" MAKE-CLEAN.TEXT ALEX/MAKE/CLEAN.TEXT ; case $? in 0) ok=$((ok+1));; 3) skip=$((skip+1));; *) fail=$((fail+1));; esac

# The Lisa OS source files:
python3 ../LisaFileSystemToolPerFile.py add "$IMAGE" "$APPS/APBG/apbg-BG1.0.TEXT.unix.txt" "apbg/BG1/0.TEXT" ; case $? in 0) ok=$((ok+1));; 3) skip=$((skip+1));; *) fail=$((fail+1));; esac
